# Step 1: Create validate_password function
def validate_password(password):
    if len(password) < 8:
        raise ValueError("Password must be at least 8 characters")
    if " " in password:
        raise ValueError("Password cannot contain spaces")
    return "Password is valid!"

# Step 5: Test with different passwords
print("Testing 'Secure123':")
try:
    result = validate_password("Secure123")
    print(result)
except ValueError as e:
    print(f"Error: {e}")

print("\nTesting 'short':")
try:
    result = validate_password("short")
    print(result)
except ValueError as e:
    print(f"Error: {e}")

print("\nTesting 'has space':")
try:
    result = validate_password("has space")
    print(result)
except ValueError as e:
    print(f"Error: {e}")

